CREATE SCHEMA IF NOT EXISTS registry;

CREATE TABLE IF NOT EXISTS registry.feature (
    "index" int8 GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "name" text,
    "type" text,
    "owner" text,
    "source" text,
    "description" text,
    "version" text,
    "lifetime" text,
    "created" timestamp
);


CREATE TABLE IF NOT EXISTS public.web_analytics (
	"index" int8 NULL,
	hit_datetime timestamp NULL,
	watch_id int8 NULL,
	visit_id int8 NULL,
	visit_datetime timestamp NULL,
	client_id int8 NULL,
	referer text NULL,
	start_url text NULL,
	url text NULL,
	end_url text NULL,
	visit_duration int8 NULL,
	page_views int8 NULL,
	page_goals text NULL,
	page_goals_time text NULL,
	goals_id text NULL,
	goals_datetime text NULL,
	visit_source text NULL,
	is_new_user int8 NULL,
	utm_source text NULL,
	utm_medium text NULL,
	utm_campaign text NULL,
	utm_term text NULL
);
CREATE INDEX IF NOT EXISTS ix_web_analytics_index ON public.web_analytics ("index" int8_ops);

